import { OlapTable, Stream, IngestApi, MaterializedView, Api, sql } from "@514labs/moose-lib";
import { ProductEvent } from "./datamodels/ProductEvent";

// ============= CORE INFRASTRUCTURE =============

// ClickHouse table - the persistent store
export const ProductEventTable = new OlapTable<ProductEvent>("ProductEvent", {
  orderByFields: ["event_ts", "user_id", "product_id"],
});

// Redpanda topic - buffer between ingest and table, auto-sinks into the table
export const ProductEventStream = new Stream<ProductEvent>("ProductEvent", {
  destination: ProductEventTable,
});

// HTTP ingest - POST /ingest/ProductEvent
export const ProductEventIngest = new IngestApi<ProductEvent>("ProductEvent", {
  destination: ProductEventStream,
});

// ============= MATERIALIZED VIEWS =============

// Top Products Aggregation
export interface TopProductsRow {
  product_id: string;
  views: number;
  carts: number;
  purchases: number;
  revenue: number;
}

export const TopProducts = new MaterializedView<TopProductsRow>({
  tableName: "TopProducts",
  materializedViewName: "top_products_mv",
  orderByFields: ["purchases DESC", "revenue DESC", "product_id"],
  selectStatement: sql`
    SELECT
      product_id,
      countIf(event_type = 'view') AS views,
      countIf(event_type = 'cart') AS carts,
      countIf(event_type = 'purchase') AS purchases,
      sumIf(properties['price'] AS Float64, event_type = 'purchase') AS revenue
    FROM ProductEvent
    GROUP BY product_id
  `,
  selectTables: [ProductEventTable],
});

// Conversion Funnel Aggregation
export interface ConversionFunnelRow {
  step: string;
  step_number: number;
  unique_users: number;
  total_events: number;
}

export const ConversionFunnel = new MaterializedView<ConversionFunnelRow>({
  tableName: "ConversionFunnel",
  materializedViewName: "conversion_funnel_mv",
  orderByFields: ["step_number"],
  selectStatement: sql`
    SELECT
      step,
      step_number,
      uniq(user_id) AS unique_users,
      count() AS total_events
    FROM (
      SELECT
        user_id,
        event_type AS step,
        CASE
          WHEN event_type = 'view' THEN 1
          WHEN event_type = 'cart' THEN 2
          WHEN event_type = 'purchase' THEN 3
          ELSE 0
        END AS step_number
      FROM ProductEvent
      WHERE event_type IN ('view', 'cart', 'purchase')
    )
    GROUP BY step, step_number
  `,
  selectTables: [ProductEventTable],
});

// Hourly Activity Aggregation
export interface HourlyActivityRow {
  hour: Date;
  event_type: string;
  event_count: number;
}

export const HourlyActivity = new MaterializedView<HourlyActivityRow>({
  tableName: "HourlyActivity",
  materializedViewName: "hourly_activity_mv",
  orderByFields: ["hour", "event_type"],
  selectStatement: sql`
    SELECT
      toStartOfHour(event_ts) AS hour,
      event_type,
      count() AS event_count
    FROM ProductEvent
    GROUP BY hour, event_type
  `,
  selectTables: [ProductEventTable],
});

// ============= EGRESS APIs =============

// Top Products API
interface TopProductsInput {
  limit?: number;
}

export const topProductsApi = new Api<TopProductsInput, TopProductsRow>(
  "top-products",
  async ({ limit = 10 }, { client, sql }) => {
    const result = await client.query.execute(sql`
      SELECT product_id, views, carts, purchases, revenue
      FROM TopProducts
      ORDER BY purchases DESC, revenue DESC
      LIMIT ${limit}
    `);
    return (await result.json()) as TopProductsRow[];
  }
);

// Conversion Funnel API
interface ConversionFunnelInput {}

export const conversionFunnelApi = new Api<ConversionFunnelInput, ConversionFunnelRow>(
  "conversion-funnel",
  async ({}, { client, sql }) => {
    const result = await client.query.execute(sql`
      SELECT step, step_number, unique_users, total_events
      FROM ConversionFunnel
      ORDER BY step_number
    `);
    return (await result.json()) as ConversionFunnelRow[];
  }
);

// Hourly Activity API
interface HourlyActivityInput {
  hours?: number;
}

export const hourlyActivityApi = new Api<HourlyActivityInput, HourlyActivityRow>(
  "hourly-activity",
  async ({ hours = 24 }, { client, sql }) => {
    const result = await client.query.execute(sql`
      SELECT hour, event_type, event_count
      FROM HourlyActivity
      WHERE hour >= now() - INTERVAL ${hours} HOUR
      ORDER BY hour DESC, event_type
    `);
    return (await result.json()) as HourlyActivityRow[];
  }
);

