// Top Products Aggregation
export interface TopProductsRow {
  product_id: string;
  views: number;
  carts: number;
  purchases: number;
  revenue: number;
}

export const TopProducts = new MaterializedView<TopProductsRow>({
  tableName: "TopProducts",
  materializedViewName: "top_products_mv",
  orderByFields: ["purchases", "revenue", "product_id"],
  selectStatement: sql.statement`
    SELECT
      product_id,
      countIf(event_type = 'view') AS views,
      countIf(event_type = 'cart') AS carts,
      countIf(event_type = 'purchase') AS purchases,
      sumIf(JSONExtractFloat(properties, 'price'), event_type = 'purchase') AS revenue
    FROM ProductEvent
    GROUP BY product_id
  `,
  selectTables: [ProductEventTable],
});

// Conversion Funnel Aggregation
export interface ConversionFunnelRow {
  step: string;
  step_number: number;
  unique_users: number;
  total_events: number;
}

export const ConversionFunnel = new MaterializedView<ConversionFunnelRow>({
  tableName: "ConversionFunnel",
  materializedViewName: "conversion_funnel_mv",
  orderByFields: ["step_number"],
  selectStatement: sql.statement`
    SELECT
      step,
      step_number,
      uniq(user_id) AS unique_users,
      count() AS total_events
    FROM (
      SELECT
        user_id,
        event_type AS step,
        CASE
          WHEN event_type = 'view' THEN 1
          WHEN event_type = 'cart' THEN 2
          WHEN event_type = 'purchase' THEN 3
          ELSE 0
        END AS step_number
      FROM ProductEvent
      WHERE event_type IN ('view', 'cart', 'purchase')
    )
    GROUP BY step, step_number
  `,
  selectTables: [ProductEventTable],
});

// Hourly Activity Aggregation
export interface HourlyActivityRow {
  hour: Date;
  event_type: string;
  event_count: number;
