const express = require('express');
const { createClient } = require('@clickhouse/client');

const app = express();
const port = 3001;

// ClickHouse client configuration
const clickhouse = createClient({
  url: 'http://localhost:18123',
  username: 'panda',
  password: 'pandapass',
  database: 'local'
});

// Middleware
app.use(express.json());

// Enable CORS
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
  next();
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'healthy' });
});

// Top Products API
app.get('/api/top-products', async (req, res) => {
  try {
    const limit = parseInt(req.query.limit) || 10;

    const result = await clickhouse.query({
      query: `SELECT * FROM TopProducts LIMIT ${limit}`,
      format: 'JSON'
    });

    const data = await result.json();
    res.json(data.data);
  } catch (error) {
    console.error('Error fetching top products:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Conversion Funnel API
app.get('/api/conversion-funnel', async (req, res) => {
  try {
    const result = await clickhouse.query({
      query: 'SELECT * FROM ConversionFunnel',
      format: 'JSON'
    });

    const data = await result.json();
    res.json(data.data);
  } catch (error) {
    console.error('Error fetching conversion funnel:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Hourly Activity API
app.get('/api/hourly-activity', async (req, res) => {
  try {
    const hours = parseInt(req.query.hours) || 24;

    const result = await clickhouse.query({
      query: `SELECT * FROM HourlyActivity WHERE hour >= now() - INTERVAL ${hours} HOUR ORDER BY hour DESC, event_type`,
      format: 'JSON'
    });

    const data = await result.json();
    res.json(data.data);
  } catch (error) {
    console.error('Error fetching hourly activity:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.listen(port, () => {
  console.log(`Analytics API server running at http://localhost:${port}`);
});

module.exports = app;

